'use strict';
const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict'),path=require('node:path');
const root=path.resolve(__dirname,'..');
function makeContext(before=false){const c=vm.createContext({window:{},console,addEventListener(){},Number,Math});vm.runInContext(fs.readFileSync(path.join(root,'dist/core.js'),'utf8'),c);for(const id of ['coffee','toaster','vending'])vm.runInContext(fs.readFileSync(before?path.join(process.env.FOOD_OBSERVATION_BASELINE_DIR||path.join(__dirname,'optional-food-observation-baseline'),id+'-observation-before.js'):path.join(root,'dist/scenes',id+'.js'),'utf8'),c);return c;}
const context=makeContext(),evaluate=code=>vm.runInContext(code,context),snapshots=[];
function fixture(id){const cfg=context.window.SCENES[id](),callbacks=new Set();cfg.state.pal='mint';cfg.state.az=105;const ui={animate(fn,options={}){callbacks.add({fn,options})},flash(){},invalidate(){}};return {id,cfg,s:cfg.state,callbacks,ui,act(name,data={}){cfg.acts[name](cfg.state,{dataset:data},ui)},button(label){cfg.buttons.find(b=>b.label===label).onClick(cfg.state,ui)},tick(seconds,rate=1){for(let t=0;t<seconds-1e-9;t+=.02){for(const d of [...callbacks])if(d.fn(Math.min(.02,seconds-t)*(d.options.realtime?1:rate))===false)callbacks.delete(d)}},finish(){let n=0;while(callbacks.size&&n++<1500)this.tick(.02);assert.equal(callbacks.size,0,'motion terminates')},render(){evaluate('setCam(45,35.264);setLight(105);');const svg=cfg.scene(cfg.state,evaluate('PALS.mint'));return cfg.scene.layers?cfg.scene.layers.map(l=>l.svg).join(''):svg;}};}
const pct=n=>Math.round(n*100)+'%',finish=(f,k,data)=>{f.act(k,data);f.finish()};let checks=0;
function check(f,label){const before=JSON.stringify(f.s),o=f.cfg.observation;assert.ok(o&&o.slow);assert.equal(o.title,'看原理');assert.match(o.intro,/简化示意/);const result=o.read(f.s);assert.equal(JSON.stringify(f.s),before,'observation must not mutate mechanism');assert.ok(result.stage&&result.stage.length<=12);assert.ok(result.text&&result.text.length<=80,`${f.id}/${label}: ${result.text.length} chars`);const markup=f.render(),parts=new Set([...markup.matchAll(/data-observe-part="([^"]+)"/g)].map(m=>m[1]));for(const active of result.active)assert.ok(parts.has(active),f.id+'/'+label+': active part rendered '+active);assert.ok(result.active.length,'each stage has a relevant real component');assert.equal(result.readouts.length,4);const r=Object.fromEntries(result.readouts.map(x=>[x.label,x.value]));for(const item of result.readouts){assert.equal(typeof item.value,'string');assert.ok(!/undefined|NaN|Infinity/.test(item.value));}
 if(f.id==='coffee'){assert.equal(r['豆仓余量'],pct(f.s.beans));assert.equal(r['粉碗粉量'],pct(f.s.ground));assert.equal(r['示意压力'],pct(f.s.pressure));assert.equal(r['咖啡液量'],pct(f.s.fill));if(f.s.phase!=='brewing')assert.equal(f.s.pressure,0);}
 if(f.id==='toaster'){assert.equal(r['设定时长'],(3+2*f.s.level)+' 秒（示意）');assert.equal(r['发热丝'],f.s.phase==='heating'?'通电':'断电');assert.equal(r['烘烤进度'],pct(f.s.progress));assert.equal(r['托架压下'],pct(f.s.lever));assert.match(o.intro,/没有模拟或测量真实温度/);}
 if(f.id==='vending'){assert.equal(r['暂存 / 保留币'],f.s.tokens+' / '+f.s.reservedCoin+' 枚');assert.equal(r['可售 / 保留库存'],f.s.stock.reduce((a,b)=>a+b,0)+' / '+(f.s.delivered===null?0:1)+' 罐');assert.equal(r['已领取'],f.s.collected+' 罐');if(f.s.delivered===null)assert.equal(r['饮料位置'],'无待取饮料');}
 assert.ok(!/<(?:rect|path)[^>]*(?:fill="transparent"|opacity="0")/.test(markup),'no invisible interaction geometry');snapshots.push({id:f.id,label,state:JSON.parse(before),markup});checks++;
}
for(const id of ['coffee','toaster','vending']){const f=fixture(id);check(f,'initial');const seq=id==='coffee'?['beans','grind','filter','cup','brew','milk','collect']:id==='toaster'?['load','level','start','collect']:['token','choose','collect','token','refund'];for(const k of seq){f.act(k,{i:'2'});check(f,k+'-begin');f.tick(.3);check(f,k+'-mid');f.finish();check(f,k+'-end');}}
// Intermediate phases which span more than one causal operation.
const c=fixture('coffee');for(const k of ['beans','grind','filter','cup'])finish(c,k);c.act('brew');c.tick(.3);assert.equal(c.s.fill,0);assert.ok(c.s.pressure>0);assert.equal(c.cfg.observation.read(c.s).stage,'预浸润');check(c,'preinfusion');c.tick(.5);assert.ok(c.s.fill>0);check(c,'flow-start');c.tick(4.4);assert.ok(c.s.pressure<1);check(c,'pressure-release');c.act('brew');const partial=c.s.fill;c.finish();assert.equal(c.s.pressure,0);assert.equal(c.s.fill,partial);check(c,'stopped-flow');
// Stopping just after the first drops must not erase them when extraction is restarted.
const tiny=fixture('coffee');for(const k of ['beans','grind','filter','cup'])finish(tiny,k);tiny.act('brew');tiny.tick(.70);tiny.act('brew');const tinyFill=tiny.s.fill;assert.ok(tinyFill>0&&tinyFill<.02);check(tiny,'tiny-stopped');tiny.act('brew');assert.equal(tiny.s.brewT,0);tiny.tick(.2);assert.equal(tiny.s.fill,tinyFill);check(tiny,'tiny-restart-preinfusion');tiny.finish();assert.equal(tiny.s.fill,1);
for(const level of [1,2,3]){const t=fixture('toaster');finish(t,'load');t.cfg.buttons.find(b=>b.label==='选择焦度').choices(t.s)[level-1].onClick(t.s,t.ui);t.finish();t.act('start');t.tick(.6);assert.equal(t.s.phase,'heating');check(t,'heating-begin-'+level);t.tick((3+2*level)/2);check(t,'heating-mid-'+level);t.finish();check(t,'released-'+level);assert.equal(t.s.progress,1);assert.equal(t.cfg.observation.read(t.s).readouts.find(x=>x.label==='发热丝').value,'断电');}
const cancel=fixture('toaster');finish(cancel,'load');cancel.act('start');cancel.act('stop');cancel.tick(.75);assert.equal(cancel.s.lift,0,'unmoved carrier must not jump');check(cancel,'cancel-before-motion');cancel.finish();finish(cancel,'collect');finish(cancel,'load');cancel.act('start');cancel.tick(2.6);const brown=cancel.s.progress;cancel.act('stop');check(cancel,'cancel-heating-begin');cancel.tick(.2);check(cancel,'cancel-heating-mid');cancel.finish();assert.equal(cancel.s.progress,brown);check(cancel,'cancel-heating-end');
const v=fixture('vending');v.act('choose',{i:'1'});check(v,'selected-without-coin');finish(v,'token');v.act('choose',{i:'1'});check(v,'release-begin');v.tick(.3);check(v,'release-mid');v.tick(.5);check(v,'gravity-fall');v.tick(1.3);assert.equal(v.s.phase,'deliver');check(v,'delivery-mid');v.finish();check(v,'at-pickup');finish(v,'collect');v.button('补满库存');check(v,'restock-begin');v.tick(.4);check(v,'restock-mid');v.finish();check(v,'restock-end');
// Early stop/reset repeated without advancing the old driver cannot revive stale work.
for(const id of ['coffee','toaster','vending']){const f=fixture(id),start=id==='coffee'?'beans':id==='toaster'?'load':'token';for(let i=0;i<30;i++){f.act(start);f.tick(.01);if(id==='vending')f.button('重新开始');else f.act('reset');check(f,'repeat-reset-'+i);}f.finish();assert.equal(f.s.phase,id==='vending'?'idle':'empty');assert.equal(f.callbacks.size,0);}
// Simulated 1/4x supplies a quarter as much mechanism time, not a second clock.
for(const [id,k,key]of [['coffee','beans','beans'],['toaster','load','loadT'],['vending','token','coinT']]){const fast=fixture(id),slow=fixture(id);fast.act(k);slow.act(k);fast.tick(.4);slow.tick(.4,.25);assert.ok(Math.abs(fast.s[key]/4-slow.s[key])<1e-9);check(slow,'quarter-speed');slow.finish();check(slow,'quarter-speed-end');}
// Optional developer-only baseline compares exact geometry after removing just our semantic wrappers.
if(process.argv.includes('--compare-baseline')){const old=makeContext(true);function unwrap(svg){const stack=[];return svg.replace(/<\/?g\b[^>]*>/g,tag=>{if(tag.startsWith('</'))return stack.pop()?'':tag;const remove=tag.includes('data-observe-part=');stack.push(remove);return remove?'':tag;});}for(const snapshot of snapshots){const cfg=old.window.SCENES[snapshot.id]();Object.assign(cfg.state,snapshot.state);vm.runInContext('setCam(45,35.264);setLight(105);',old);const base=cfg.scene(cfg.state,vm.runInContext('PALS.mint',old)),markup=cfg.scene.layers?cfg.scene.layers.map(l=>l.svg).join(''):base;assert.equal(unwrap(snapshot.markup),markup,snapshot.id+'/'+snapshot.label+': wrappers must preserve rendered geometry');}}
console.log(`PASS: ${checks} food observation stages, live numeric/active-part checks, early-stop and repeat-reset cases, 1/4x simulation;${process.argv.includes('--compare-baseline')?' exact geometry preserved in every snapshot;':''} no browser or publication used.`);
